CREATE TABLE `PORTAL_PAGES` (
  `ID` bigint NOT NULL AUTO_INCREMENT,
  `SITE_ID` bigint NOT NULL,
  `SHOW_MAX_WINDOW` tinyint DEFAULT '0',
  `DISPLAY_NAME` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `NAME` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `DESCRIPTION` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `FACTORY_ID` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `PAGE_BODY` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `HIDE_SHARED_LAYOUT` tinyint DEFAULT '0',
  `PAGE_TYPE` int NOT NULL DEFAULT '0',
  `LINK` text,
  `PROFILES` varchar(2000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `SHOW_SHARED_LAYOUT` tinyint DEFAULT '0',
  PRIMARY KEY (`ID`),
  UNIQUE KEY `UK_PORTAL_SITE_PAGE_NAME` (`SITE_ID`,`NAME`),
  CONSTRAINT `FK_PORTAL_PAGE_SITE` FOREIGN KEY (`SITE_ID`) REFERENCES `PORTAL_SITES` (`ID`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=124 DEFAULT CHARSET=utf8mb3;
